der-hover, #334155); }\r\n.shop-page-btn:disabled { opacity: 0.25; cursor: default; border-color: var(--border-color, #11151a); }\r\n.itemshop-page-ellipsis { color: var(--border-hover, #334155); padding: 5px 4px; font-family: monospace; }\r\n.itemshop-modal-box { width: 440px; transition: border-color 0.3s; }\r\n.itemshop-modal-box.tier-epic { border-top-color: var(--gold, #e6cc80); box-shadow: 0 -2px 15px rgba(230,204,128,0.1); }\r\n.itemshop-modal-header { display: flex; justify-content: space-between; align-items: center; margin-bottom: 16px; border-bottom: 1px solid var(--border-color, #1a2433); padding-bottom: 12px; }\r\n.itemshop-modal-title { font-family: \'Cinzel\', serif; font-size: 0.85em; letter-spacing: 2px; color: var(--text-color, #e2e8f0); text-transform: uppercase; margin: 0; }\r\n.itemshop-modal-close { background: none; border: none; color: var(--text-muted, #475569); font-size: 20px; cursor: pointer; transition: color 0.2s; }\r\n.itemshop-modal-close:hover { color: #fff; }\r\n.itemshop-modal-body { font-size: 13px; line-height: 1.7; }\r\n.itemshop-modal-loading { text-align: center; color: var(--text-muted); padding: 20px; }\r\n.itemshop-error-inline { color: #ef4444; }\r\n.itemshop-item-name { font-size: 16px; font-family: \'Cinzel\', serif; font-weight: bold; margin-bottom: 2px; }\r\n.itemshop-item-level { color: var(--text-muted, #475569); font-size: 11px; font-family: monospace; margin-bottom: 10px; }\r\n.itemshop-item-effect { color: var(--text-muted, #94a3b8); font-style: italic; background: rgba(0,0,0,0.2); padding: 10px; border: 1px solid var(--border-color, #11151a); border-radius: 2px; }\r\n.itemshop-modal-listings { margin-top: 14px; max-height: 250px; overflow-y: auto; }\r\n.itemshop-modal-listings::-webkit-scrollbar { width: 6px; }\r\n.itemshop-modal-listings::-webkit-scrollbar-track { background: rgba(0,0,0,0.2); }\r\n.itemshop-modal-listings::-webkit-scrollbar-thumb { background: var(--border-color, #1f2933); border-radius: 3px; }\