	(150, 'hero', 'default', '.cms-hero {\r\n    position: relative;\r\n    width: 100%;\r\n    background-size: cover;\r\n    background-position: center;\r\n    background-color: #0a0a0a;\r\n    display: flex;\r\n    flex-direction: column;\r\n    overflow: hidden;\r\n}\r\n.cms-hero-overlay {\r\n    position: absolute; inset: 0;\r\n    background: linear-gradient(180deg, rgba(5,4,3,0.55) 0%, rgba(5,4,3,0.75) 55%, rgba(5,4,3,0.97) 100%);\r\n}\r\n\r\n\r\n.cms-hero--large { min-height: 100vh; align-items: center; justify-content: center; }\r\n.cms-hero-content {\r\n    position: relative; z-index: 2;\r\n    text-align: center;\r\n    padding: 140px 20px 60px;\r\n    max-width: 900px;\r\n}\r\n.cms-hero-wordmark { max-width: 340px; width: 60%; margin-bottom: 10px; filter: drop-shadow(0 0 30px rgba(0,0,0,0.6)); }\r\n.cms-hero-title {\r\n    font-family: \'Cinzel\', serif; font-weight: 900;\r\n    font-size: clamp(2.4em, 7vw, 5em);\r\n    color: #f2ede0;\r\n    letter-spacing: 4px;\r\n    margin: 10px 0 6px 0;\r\n    text-shadow: 0 4px 40px rgba(0,0,0,0.7);\r\n}\r\n.cms-hero-tagline {\r\n    font-family: \'Cormorant Garamond\', serif; font-style: italic;\r\n    font-size: 1.3em; color: #c9c2ac;\r\n    margin: 0 0 40px 0; letter-spacing: 0.5px;\r\n}\r\n.cms-hero-actions { display: flex; gap: 16px; justify-content: center; flex-wrap: wrap; }\r\n.cms-hero-btn {\r\n    font-family: \'Cinzel\', serif; font-size: 0.8em; letter-spacing: 2px; text-transform: uppercase;\r\n    padding: 15px 30px; text-decoration: none; display: inline-flex; align-items: center; gap: 10px;\r\n    transition: all 0.3s ease; border: 1px solid transparent;\r\n}\r\n.cms-hero-btn--primary { background: var(--gold, #c5a059); color: #000; font-weight: 700; }\r\n.cms-hero-btn--primary:hover { background: #e8d48b; box-shadow: 0 0 30px rgba(197,160,89,0.4); transform: translateY(-2px); }\r\n.cms-hero-btn--ghost { border-color: rgba(255,255,255,0.3); color: #eee; }\r\n.cms-hero-btn--ghost:hover { border-color: #fff; background: rgba(255,255,255,0.06); }\r\n\r\n.cms-hero-scroll-hint { margin-top: 70px; color: rgba(255,255,255,0.35); font-size: 1.3em; animation: cmsHeroBounce 2.2s infinite; }\r\n@keyframes cmsHeroBounce { 0%,100% { transform: translateY(0); opacity: 0.35; } 50% { transform: translateY(8px); opacity: 0.7; } }\r\n\r\n.cms-hero-realms {\r\n    position: relative; z-index: 2;\r\n    display: flex; align-items: center; justify-content: center; gap: 20px;\r\n    padding: 0 0 40px 0; flex-wrap: wrap;\r\n}\r\n.cms-hero-realm { font-family: \'Cinzel\', serif; font-size: 0.72em; letter-spacing: 2px; text-transform: uppercase; color: #999; display: flex; align-items: center; gap: 8px; }\r\n.cms-hero-realm i { font-size: 0.5em; }\r\n.cms-hero-realm--alb i { color: #c0392b; }\r\n.cms-hero-realm--hib i { color: #27ae60; }\r\n.cms-hero-realm--mid i { color: #2980b9; }\r\n.cms-hero-realm-sep { width: 1px; height: 12px; background: rgba(255,255,255,0.15); }\r\n\r\n\r\n.cms-hero--compact { min-height: 140px; align-items: flex-end; }\r\n.cms-hero-overlay--compact { background: linear-gradient(180deg, rgba(5,4,3,0.4) 0%, rgba(5,4,3,0.85) 85%, #050505 100%); }\r\n.cms-hero-compact-content { position: relative; z-index: 2; width: 100%; max-width: 1400px; margin: 0 auto; padding: 110px 40px 20px; }\r\n.cms-hero-breadcrumb { display: none; }\r\n.cms-hero-breadcrumb a { color: #888; text-decoration: none; }\r\n.cms-hero-breadcrumb a:hover { color: var(--gold, #c5a059); }\r\n.cms-hero-breadcrumb-sep { margin: 0 8px; opacity: 0.4; }\r\n.cms-hero-compact-title { font-family: \'Cinzel\', serif; font-size: clamp(0.9em, 1.8vw, 1.15em); color: #b8ac82; margin: 0; font-weight: 400; letter-spacing: 4px; text-transform: uppercase; text-shadow: 0 1px 0 rgba(255,255,255,0.06), 0 2px 6px rgba(0,0,0,0.6); }\r\n\r\n@media screen and (max-width: 768px) {\r\n    .cms-hero-content { padding: 30px 20px 40px; }\r\n    .cms-hero-compact-content { padding: 16px 20px 16px; }\r\n    .cms-hero--compact { min-height: 60px; }\r\n    .cms-hero-wordmark { width: 80%; }\r\n    .cms-hero-compact-title { display: none; }\r\n}\r\n.cms-hero-frame { position: absolute; inset: 14px; border: 1px solid rgba(197,160,89,0.18); pointer-events: none; z-index: 2; }\r\n.cms-hero-frame::before, .cms-hero-frame::after {\r\n    content: \'\'; position: absolute; width: 18px; height: 18px; border: 1px solid var(--gold, #c5a059);\r\n}\r\n.cms-hero-frame::before { top: -1px; left: -1px; border-right: none; border-bottom: none; }\r\n.cms-hero-frame::after  { bottom: -1px; right: -1px; border-left: none; border-top: none; }\r\n.cms-hero-embers { position: absolute; inset: 0; overflow: hidden; pointer-events: none; z-index: 1; }\r\n.cms-hero-embers span {\r\n    position: absolute; bottom: -10px; width: 3px; height: 3px; border-radius: 50%;\r\n    background: var(--gold, #c5a059); box-shadow: 0 0 6px 1px rgba(197,160,89,0.6);\r\n    opacity: 0; animation: cmsEmberRise 7s linear infinite;\r\n}\r\n.cms-hero-embers span:nth-child(1) { left: 8%;  animation-delay: 0s;   }\r\n.cms-hero-embers span:nth-child(2) { left: 24%; animation-delay: 1.4s; }\r\n.cms-hero-embers span:nth-child(3) { left: 47%; animation-delay: 2.8s; }\r\n.cms-hero-embers span:nth-child(4) { left: 68%; animation-delay: 4.2s; }\r\n.cms-hero-embers span:nth-child(5) { left: 88%; animation-delay: 5.6s; }\r\n@keyframes cmsEmberRise {\r\n    0%   { transform: translateY(0) translateX(0); opacity: 0; }\r\n    10%  { opacity: 0.8; }\r\n    100% { transform: translateY(-160px) translateX(12px); opacity: 0; }\r\n}\r\n.cms-hero-realm-bar {\r\n    width: 64px; height: 2px; margin-top: 14px;\r\n    background: var(--realm-gradient, linear-gradient(90deg,#c0392b,#c5a059,#27ae60,#c5a059,#2980b9));\r\n    opacity: 0.85;\r\n}\r\n.cms-hero-compact-title {\r\n    text-shadow: 0 1px 0 rgba(255,255,255,0.06), 0 2px 6px rgba(0,0,0,0.6), 0 0 24px rgba(197,160,89,0.12);\r\n}\r\n@media screen and (max-width: 768px) {\r\n    .cms-hero-frame, .cms-hero-embers { display: none; }\r\n    .cms-hero-realm-bar { margin-top: 8px; }\r\n}\r\n@media (prefers-reduced-motion: reduce) { .cms-hero-embers span { animation: none; opacity: 0; } }\r\n.cms-hero--compact { min-height: 170px; }\r\n.cms-hero-frame { inset: 10px; }\r\n.cms-hero-frame::before, .cms-hero-frame::after { width: 22px; height: 22px; }\r\n.cms-hero-realm-bar { margin-top: 10px; }\r\n\r\n\r\n\r\n\r\n\r\n.cms-hero-frame { display: none !important; }\r\n\r\n\r\n.cms-hero--compact {\r\n    min-height: 190px;\r\n    box-shadow: inset 0 -60px 80px -30px rgba(5,4,3,0.95),\r\n                inset 0 0 140px rgba(0,0,0,0.6);\r\n}\r\n.cms-hero-overlay--compact {\r\n    background:\r\n        radial-gradient(120% 80% at 50% 0%, rgba(197,160,89,0.06) 0%, transparent 55%),\r\n        linear-gradient(180deg, rgba(5,4,3,0.35) 0%, rgba(5,4,3,0.82) 82%, #050505 100%);\r\n}\r\n\r\n\r\n.cms-hero-breadcrumb {\r\n    display: flex !important; align-items: center; gap: 4px;\r\n    font-family: \'Cinzel\', serif; font-size: 0.62em; letter-spacing: 2px;\r\n    text-transform: uppercase; margin-bottom: 10px; opacity: 0.85;\r\n}\r\n.cms-hero-breadcrumb a { color: #8a8272; }\r\n.cms-hero-breadcrumb a:hover { color: var(--gold, #c5a059); text-shadow: 0 0 8px rgba(197,160,89,0.5); }\r\n.cms-hero-breadcrumb-sep { color: rgba(197,160,89,0.5); }\r\n.cms-hero-breadcrumb span:last-child { color: #c9b98a; }\r\n\r\n\r\n.cms-hero-compact-title {\r\n    display: block !important;\r\n    font-size: clamp(1.4em, 3vw, 2.4em) !important;\r\n    letter-spacing: 6px !important;\r\n    background: linear-gradient(180deg, #f4e6b8 0%, #c5a059 45%, #8e6d2d 75%, #e8d48b 100%);\r\n    -webkit-background-clip: text; background-clip: text;\r\n    -webkit-text-fill-color: transparent; color: transparent;\r\n    filter: drop-shadow(0 2px 4px rgba(0,0,0,0.7)) drop-shadow(0 0 22px rgba(197,160,89,0.25));\r\n}\r\n\r\n\r\n.cms-hero-realm-bar {\r\n    position: relative; width: 200px; height: 3px; margin-top: 14px; overflow: hidden;\r\n    background: var(--realm-gradient, linear-gradient(90deg,#c0392b,#c5a059,#27ae60,#c5a059,#2980b9));\r\n    opacity: 0.9; border-radius: 2px;\r\n}\r\n.cms-hero-realm-bar::after {\r\n    content: \'\'; position: absolute; top: 0; left: -40%; width: 40%; height: 100%;\r\n    background: linear-gradient(90deg, transparent, rgba(255,255,255,0.85), transparent);\r\n    animation: heroSweep 3.5s ease-in-out infinite;\r\n}\r\n@keyframes heroSweep { 0% { left: -40%; } 60%,100% { left: 120%; } }\r\n\r\n\r\n.cms-hero-embers span {\r\n    width: 4px; height: 4px;\r\n    box-shadow: 0 0 8px 2px rgba(197,160,89,0.7);\r\n    animation-duration: 8s;\r\n}\r\n\r\n@media screen and (max-width: 768px) {\r\n    .cms-hero--compact { min-height: 90px; }\r\n    .cms-hero-compact-title { font-size: 1.1em !important; letter-spacing: 3px !important; }\r\n    .cms-hero-realm-bar { width: 120px; margin-top: 8px; }\r\n    .cms-hero-embers { display: none; }\r\n}\r\n@media (prefers-reduced-motion: reduce) {\r\n    .cms-hero-realm-bar::after { animation: none; display: none; }\r\n}\r\n\n\n\n\n\n\n.cms-hero--compact {\n    min-height: 210px;\n    align-items: flex-end;\n    background-color: #06060a;\n    box-shadow: inset 0 -70px 90px -45px #050506,\n                inset 0 0 170px rgba(0,0,0,0.7);\n}\n\n.cms-hero-overlay--compact {\n    background:\n        \n        radial-gradient(120% 95% at 50% -25%, rgba(197,160,89,0.075) 0%, transparent 60%),\n        linear-gradient(180deg, rgba(5,5,6,0.42) 0%, rgba(5,5,6,0.74) 60%, #050506 100%);\n}\n\n\n.cms-hero--has-image {\n    min-height: 320px;\n    background-size: cover;\n    background-position: center 42%;\n}\n.cms-hero--has-image .cms-hero-overlay--compact {\n    background:\n        linear-gradient(90deg, rgba(5,5,6,0.90) 0%, rgba(5,5,6,0.55) 42%, rgba(5,5,6,0.20) 100%),\n        linear-gradient(180deg, rgba(5,5,6,0.55) 0%, rgba(5,5,6,0.45) 45%, rgba(5,5,6,0.92) 88%, #050506 100%);\n}\n\n\n.cms-hero-breadcrumb {\n    font-size: 0.60em;\n    letter-spacing: 2.6px;\n    margin-bottom: 12px;\n    opacity: 1;\n}\n.cms-hero-breadcrumb a { color: var(--ald-ink-mute); transition: color 0.2s; }\n.cms-hero-breadcrumb a:hover { color: var(--ald-gold); text-shadow: none; }\n.cms-hero-breadcrumb-sep { color: rgba(197,160,89,0.35); }\n.cms-hero-breadcrumb span:last-child { color: var(--ald-ink-dim); }\n\n\n.cms-hero-compact-title {\n    font-size: clamp(1.7em, 3.6vw, 3.1em) !important;\n    font-weight: 500;\n    letter-spacing: 8px !important;\n    background: linear-gradient(180deg, #f6ead0 0%, #d9bb7c 38%, #a9853f 72%, #e0c690 100%);\n    -webkit-background-clip: text; background-clip: text;\n    -webkit-text-fill-color: transparent; color: transparent;\n    filter: drop-shadow(0 2px 3px rgba(0,0,0,0.85));\n}\n\n\n.cms-hero-realm-bar {\n    position: relative;\n    width: 340px; max-width: 64vw; height: 11px;\n    margin-top: 16px;\n    background: none !important;\n    border-radius: 0;\n    opacity: 1;\n    overflow: visible;\n}\n.cms-hero-realm-bar::before {\n    content: \'\';\n    position: absolute; top: 50%; left: 0; right: 0; height: 1px;\n    transform: translateY(-50%);\n    background: linear-gradient(90deg,\n        transparent 0%,\n        rgba(197,160,89,0.45) 22%,\n        rgba(197,160,89,0.45) 78%,\n        transparent 100%);\n    animation: none;\n}\n.cms-hero-realm-bar::after {\n    content: \'\';\n    position: absolute; top: 0; left: 50%;\n    width: 11px; height: 11px; margin-left: -5.5px;\n    background: var(--orn-diamond) center / 11px 11px no-repeat;\n    animation: none !important;\n    \n    box-shadow: 0 0 0 4px #070709;\n    border-radius: 50%;\n}\n\n\n.cms-hero-embers span {\n    width: 2px; height: 2px;\n    background: var(--ald-gold);\n    box-shadow: 0 0 5px 1px rgba(197,160,89,0.35);\n    animation-duration: 14s;\n    opacity: 0;\n}\n.cms-hero-embers span:nth-child(3),\n.cms-hero-embers span:nth-child(4),\n.cms-hero-embers span:nth-child(5) { display: none; }\n\n@media screen and (max-width: 900px) {\n    .cms-hero--compact { min-height: 128px; }\n    .cms-hero-compact-title { font-size: 1.25em !important; letter-spacing: 4px !important; }\n    .cms-hero-realm-bar { width: 200px; margin-top: 10px; }\n    .cms-hero-embers { display: none; }\n}\n@media (prefers-reduced-motion: reduce) {\n    .cms-hero-embers span { animation: none; opacity: 0; }\n}\n', 'Large + compact hero header component (Blackthorn redesign)', '2026-08-09 05:27:55', 1),
	(243, 'maintenance_page', 'default', '* { margin:0; padding:0; box-sizing:border-box; }\r\nbody { background:#050505; color:#d4af37; display:flex; justify-content:center; align-items:center; min-height:100vh; font-family:serif; }\r\n.box { border:1px solid #d4af37; padding:50px; text-align:center; box-shadow:0 0 30px rgba(212,175,55,0.3); max-width:600px; width:90%; background:#000; overflow-wrap:break-word; word-break:break-word; }\r\n.box img { max-width:min(250px, 100%); height:auto; margin-bottom:20px; }\r\n.box h1 { font-family:\'Cinzel\',serif; font-size:clamp(1.4rem, 7vw, 2.4rem); letter-spacing:clamp(1px, 1.2vw, 5px); line-height:1.3; margin-bottom:20px; overflow-wrap:break-word; word-break:break-word; }\r\n.box p { color:#fff; font-style:italic; font-family:sans-serif; line-height:1.6; margin-bottom:30px; overflow-wrap:break-word; word-break:break-word; }\r\n.box a { display:inline-block; color:#d4af37; text-decoration:none; border:1px solid #d4af37; padding:10px 20px; font-size:0.8em; letter-spacing:2px; font-family:\'Cinzel\',serif; transition:background 0.2s; }\r\n.box a:hover { background:rgba(212,175,55,0.1); }\r\n@media (max-width: 480px) {\r\n    .box { padding:30px 20px; width:94%; }\r\n}\n\n\n@media (max-width: 600px) {\n    .box {\n        padding: 24px 16px !important;\n        width: 94% !important;\n        max-width: 94% !important;\n        box-sizing: border-box !important;\n    }\n    .box h1 {\n        font-size: clamp(1.1rem, 6vw, 2.4rem) !important;\n        letter-spacing: clamp(0px, 0.5vw, 3px) !important;\n        max-width: 100% !important;\n        overflow-wrap: anywhere !important;\n        word-break: break-word !important;\n        hyphens: auto !important;\n    }\n}\n', 'Standalone maintenance/down-for-maintenance page (index.php maintenance.lock screen)', '2026-08-09 05:47:11', 1),
	(246, 'suit_creator', 'default', '.sc-paperdoll-container { position: relative; width: 100%; max-width: 480px; height: 480px; margin: 0 auto; background: radial-gradient(circle at center, rgba(30,25,20,0.6) 0%, rgba(5,5,5,0.95) 70%); border: 1px solid rgba(197,160,89,0.2); border-radius: 6px; display: none; box-shadow: inset 0 0 30px rgba(0,0,0,0.8); }\n.sc-paperdoll-container.active { display: block; }\n.sc-paperdoll-silhouette { position: absolute; inset: 10%; display: flex; align-items: center; justify-content: center; opacity: 0.15; pointer-events: none; }\n.sc-paperdoll-silhouette i { font-size: 16em; color: #c5a059; }\n.sc-paperdoll-node { position: absolute; width: 90px; height: 52px; transform: translate(-50%, -50%); background: rgba(10,10,10,0.9); border: 1px solid #222; border-radius: 4px; padding: 4px 6px; box-sizing: border-box; cursor: pointer; transition: border-color 0.2s, box-shadow 0.2s, transform 0.2s; }\n.sc-paperdoll-node:hover { border-color: #c5a059; box-shadow: 0 0 10px rgba(197,160,89,0.3); transform: translate(-50%, -50%) scale(1.05); z-index: 10; }\n.sc-paperdoll-node.filled { border-color: rgba(197,160,89,0.5); background: linear-gradient(180deg, rgba(20,18,15,0.95), rgba(8,7,6,0.98)); }\n.sc-paperdoll-node-title { font-size: 0.62em; color: #c5a059; text-transform: uppercase; font-family: \'Cinzel\', serif; font-weight: bold; letter-spacing: 0.5px; }\n.sc-paperdoll-node-item { font-size: 0.65em; color: #777; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; margin-top: 2px; }', 'Suit Creator – Paperdoll UI Styles', '2026-08-05 04:00:41', 1),
	(249, 'user_edit', 'default', '.ue-container { background: #0c0c0c; border: 1px solid #222; padding: 40px; border-top: 3px solid #d4af37; max-width: 600px; margin: 40px auto; font-family: Arial, sans-serif; box-shadow: 0 0 30px #000; }\r\n.ue-header { display: flex; justify-content: space-between; align-items: center; margin-bottom: 30px; }\r\n.ue-title { color: #d4af37; text-transform: uppercase; margin: 0; letter-spacing: 2px; font-family: "Cinzel", serif; }\r\n.ue-back-link { color: #666; text-decoration: none; font-size: 11px; text-transform: uppercase; border: 1px solid #333; padding: 5px 10px; }\r\n.ue-field { margin-bottom: 25px; }\r\n.ue-label { color: #555; display: block; font-size: 10px; text-transform: uppercase; margin-bottom: 8px; letter-spacing: 1px; }\r\n.ue-input { width: 100%; padding: 14px; background: #000; border: 1px solid #333; color: #fff; box-sizing: border-box; }\r\n.ue-input--disabled { background: #050505; border-color: #222; color: #555; cursor: not-allowed; }\r\n.ue-select { width: 100%; padding: 14px; background: #000; border: 1px solid #333; color: #fff; }\r\n.ue-grid-2 { display: grid; grid-template-columns: 1fr 1fr; gap: 20px; margin-bottom: 25px; }\r\n.ue-verify-box { margin-bottom: 30px; padding: 15px; background: rgba(212,175,55,0.05); border: 1px solid rgba(212,175,55,0.1); }\r\n.ue-verify-label { color: #d4af37; cursor: pointer; font-size: 13px; display: flex; align-items: center; gap: 10px; }\r\n.ue-submit { width: 100%; padding: 16px; background: #d4af37; border: none; color: #000; font-weight: bold; cursor: pointer; text-transform: uppercase; letter-spacing: 2px; transition: 0.3s; }\r\n.ue-not-found { color: orange; padding: 20px; }\r\n.ue-pw-section { margin-top: 40px; padding-top: 25px; border-top: 1px solid #222; }\r\n.ue-pw-title { color: #ff4444; font-size: 11px; text-transform: uppercase; margin-bottom: 15px; letter-spacing: 1px; }\r\n.ue-pw-row { display: flex; gap: 10px; }\r\n.ue-pw-btn { flex: 1; background: transparent; border: 1px solid #ff4444; color: #ff4444; font-weight: bold; cursor: pointer; font-size: 11px; text-transform: uppercase; transition: 0.3s; }', 'User Edit – Admin form for editing user accounts', '2026-08-05 09:13:36', 1),
	(250, 'user_view', 'default', '.uv-box { padding: 40px; border-top: 2px solid var(--gold); background: rgba(0,0,0,0.4); }\r\n.uv-layout { display: flex; gap: 40px; align-items: flex-start; }\r\n.uv-avatar-col { text-align: center; width: 150px; }\r\n.uv-avatar { width: 120px; height: 120px; border: 1px solid var(--gold); object-fit: cover; box-shadow: 0 0 15px rgba(212,175,55,0.1); }\r\n.uv-avatar-placeholder { width: 120px; height: 120px; border: 1px solid #222; display: flex; align-items: center; justify-content: center; background: #050505; }\r\n.uv-avatar-icon { font-size: 80px; color: #111; }\r\n.uv-actions { margin-top: 15px; display: flex; flex-direction: column; gap: 6px; }\r\n.uv-action-item { margin: 0; }\r\n.uv-action-btn { text-decoration: none; background: rgba(197,160,89,0.07); color: var(--glow-gold); border: 1px solid rgba(197,160,89,0.22); padding: 6px 10px; font-size: 0.58em; letter-spacing: 1.5px; display: inline-flex; align-items: center; justify-content: center; gap: 5px; transition: all 0.2s; text-transform: uppercase; font-family: "Cinzel", serif; width: 100%; box-sizing: border-box; }\r\n.uv-action-btn:hover { background: rgba(197,160,89,0.13); border-color: var(--glow-gold); }\r\n.uv-action-btn--form { background: rgba(197,160,89,0.07); border: 1px solid rgba(197,160,89,0.22); color: var(--glow-gold); cursor: pointer; }\r\n.uv-info { flex: 1; }\r\n.uv-username { margin: 0 0 10px 0; font-family: "Cinzel"; color: var(--gold); letter-spacing: 2px; }\r\n.uv-title { color: #aaa; font-style: italic; margin-top: -5px; margin-bottom: 15px; }\r\n.uv-fields { display: grid; grid-template-columns: 1fr; gap: 20px; margin-top: 25px; }\r\n.uv-field-label { display: block; margin-bottom: 5px; opacity: 0.5; }\r\n.uv-field-val { color: #ccc; }\r\n.uv-field-val--realms { font-family: "Cinzel"; font-size: 1.1em; }\r\n.uv-field--bio { border-top: 1px solid #111; padding-top: 20px; }\r\n.uv-bio { color: #888; font-style: italic; line-height: 1.6; white-space: pre-wrap; }\r\n.uv-blocked-msg { color: var(--glow-gold); text-align: center; }\r\n.uv-realm--alb { color: #F52727; }\r\n.uv-realm--mid { color: #275BF5; }\r\n.uv-realm--hib { color: #27F565; }', 'User View – Public profile page', '2026-08-05 09:14:30', 1),
	(251, 'verify', 'default', '.verify-container { max-width: 450px; margin: 60px auto; background: rgba(10,10,10,0.95); border: 1px solid rgba(212,175,55,0.3); padding: 40px; text-align: center; border-top: 3px solid #d4af37; }\r\n.verify-logo { max-width: 200px; margin-bottom: 30px; }\r\n.verify-title { color: #d4af37; font-family: "Cinzel", serif; text-transform: uppercase; letter-spacing: 4px; font-size: 1.4em; margin-bottom: 30px; }\r\n.verify-status { padding: 20px; font-size: 14px; line-height: 1.6; margin-bottom: 30px; }\r\n.verify-status-box { padding: 15px; }\r\n.verify-status-box--success { color: #00ff00; background: rgba(0,255,0,0.05); border: 1px solid rgba(0,255,0,0.2); }\r\n.verify-status-box--error { color: #ff4444; background: rgba(255,0,0,0.05); border: 1px solid rgba(255,0,0,0.2); }\r\n.btn-verify { display: inline-block; width: 100%; padding: 16px; background: transparent; border: 1px solid #d4af37; color: #d4af37; text-transform: uppercase; letter-spacing: 3px; font-weight: bold; text-decoration: none; transition: 0.4s; font-family: "Cinzel", serif; box-sizing: border-box; }\r\n.btn-verify:hover { background: #d4af37; color: #000; }', 'Verify – Email verification page', '2026-08-05 09:15:36', 1),
	(252, 'search_view', 'default', '.srch-form-box { margin-bottom: 25px; background: rgba(0,0,0,0.3); padding: 15px; }\r\n.srch-form { display: flex; gap: 10px; }\r\n.srch-input { flex: 1; background: rgba(0,0,0,0.5); border: 1px solid rgba(197,160,89,0.3); color: #ccc; padding: 12px 15px; border-radius: 4px; font-family: sans-serif; outline: none; transition: border-color 0.3s; }\r\n.srch-btn { background: rgba(197,160,89,0.1); color: #c5a059; border: 1px solid rgba(197,160,89,0.4); padding: 10px 20px; font-family: "Cinzel", serif; letter-spacing: 2px; border-radius: 4px; cursor: pointer; transition: 0.3s; }\r\n.srch-prompt { text-align: center; padding: 40px; color: #555; font-family: "Cinzel", serif; letter-spacing: 2px; font-size: 0.9em; }\r\n.srch-min-chars { border-left: 3px solid #ff4444; }\r\n.srch-section-title { color: var(--glow-gold); font-family: "Cinzel"; margin-top: 20px; }\r\n.srch-users-grid { display: grid; grid-template-columns: repeat(auto-fill, minmax(200px, 1fr)); gap: 15px; }\r\n.srch-user-card { display: flex; align-items: center; gap: 15px; padding: 10px; }\r\n.srch-user-avatar { width: 40px; height: 40px; border-radius: 50%; object-fit: cover; }\r\n.srch-results-box { padding: 0; }\r\n.srch-thread-item { display: block; padding: 15px; border-bottom: 1px solid #111; color: var(--glow-blue); text-decoration: none; }\r\n.srch-post-item { margin-bottom: 10px; }\r\n.srch-post-link { color: var(--glow-blue); font-weight: bold; display: block; margin-bottom: 5px; }\r\n.srch-post-snippet { font-size: 0.85em; color: #666; font-style: italic; }', 'Search View – Search results page', '2026-08-05 09:16:44', 1),
	(254, 'notifications', 'default', '.notif-title-icon { color: var(--glow-gold); margin-right: 15px; }\r\n.notif-markall-form { margin: 0; }\r\n.notif-markall-btn { font-size: 10px; }\r\n.notif-box { padding: 0; background: rgba(5,5,5,0.8); }\r\n.notif-list {}\r\n.notif-item { display: flex; align-items: center; justify-content: space-between; padding: 20px; border-bottom: 1px solid #111; transition: background 0.15s; }\r\n.notif-item:hover { background: rgba(255,255,255,0.02); }\r\n.notif-item--unread { background: rgba(197,160,89,0.03); border-left: 3px solid var(--glow-gold); }\r\n.notif-item--read { opacity: 0.6; border-left: 3px solid #222; }\r\n.notif-item-main { display: flex; align-items: center; gap: 20px; cursor: pointer; flex: 1; }\r\n.notif-icon { font-size: 1.2em; }\r\n.notif-icon--new { color: var(--glow-gold); }\r\n.notif-icon--read { color: #444; }\r\n.notif-content {}\r\n.notif-text { color: #eee; font-size: 0.95em; }\r\n.notif-username { color: var(--glow-blue); }\r\n.notif-thread-title { color: var(--glow-gold); font-style: italic; }\r\n.notif-date { color: #444; font-size: 0.75em; margin-top: 5px; }\r\n.notif-delete-form { margin: 0; }\r\n.notif-delete-btn { background: none; border: none; color: #333; cursor: pointer; transition: 0.3s; padding: 4px 8px; }\r\n.notif-delete-btn:hover { color: #ff4444; }\r\n.notif-empty { padding: 60px; text-align: center; color: #444; }\r\n.notif-empty-icon { font-size: 3em; display: block; margin-bottom: 20px; opacity: 0.2; }\r\n.notif-empty-text { font-style: italic; letter-spacing: 1px; }', 'Notifications – Messenger page', '2026-08-05 12:44:32', 1),
	(255, 'private_messages', 'default', '.pm-not-logged-in { color: #666; }\r\n.pm-verify-required { text-align: center; padding: 80px 20px; margin-top: 40px; background: rgba(10,10,10,0.95); border: 1px solid rgba(197,160,89,0.3); border-top: 3px solid #c5a059; box-shadow: 0 10px 30px rgba(0,0,0,0.5); }\r\n.pm-verify-icon { font-size: 3.5em; color: #c5a059; margin-bottom: 20px; display: block; }\r\n.pm-verify-title { color: #c5a059; font-family: "Cinzel", serif; letter-spacing: 2px; text-transform: uppercase; margin-bottom: 15px; }\r\n.pm-verify-desc { color: #888; font-size: 0.95em; }\r\n.pm-header { display: flex; justify-content: space-between; align-items: center; margin-bottom: 25px; }\r\n.pm-title { font-family: Cinzel; color: #c5a059; margin: 0; font-size: 14px; letter-spacing: 3px; }\r\n.pm-tabs { border-bottom: 1px solid #111; margin-bottom: 20px; display: flex; gap: 0; }\r\n.pm-tab { text-decoration: none; padding: 8px 16px; font-family: Cinzel; font-size: 10px; letter-spacing: 1px; border-bottom: 2px solid transparent; color: #444; transition: 0.2s; display: inline-flex; align-items: center; gap: 5px; }\r\n.pm-tab--active { border-bottom-color: #c5a059; color: #c5a059; }\r\n.pm-tab-icon { font-size: 8px; }\r\n.pm-unread-badge { background: #c5a059; color: #000; font-size: 9px; font-weight: bold; padding: 1px 6px; border-radius: 8px; margin-left: 6px; }\r\n.pm-row { display: flex; align-items: center; gap: 15px; padding: 12px 15px; border-bottom: 1px solid #0f0f0f; transition: background 0.15s; }\r\n.pm-row:hover { background: rgba(255,255,255,0.02); }\r\n.pm-row--unread { background: rgba(197,160,89,0.04); border-left: 2px solid #c5a059; }\r\n.pm-row-content { flex: 1; }\r\n.pm-row-link { text-decoration: none; display: block; }\r\n.pm-subject--unread { color: #ddd; font-weight: bold; }\r\n.pm-subject--read { color: #888; }\r\n.pm-row-meta { font-size: 10px; color: #555; margin-top: 3px; }\r\n.pm-row-sender { color: #c5a059; }\r\n.pm-delete-form { margin: 0; display: inline-block; }\r\n.pm-delete-btn { background: none; border: none; color: #333; cursor: pointer; font-size: 11px; transition: color 0.2s; }\r\n.pm-delete-btn:hover { color: #e74c3c; }\r\n.pm-recall-btn { background: none; border: none; color: #555; cursor: pointer; font-size: 11px; transition: color 0.2s; margin-left: 8px; }\r\n.pm-recall-btn:hover { color: #c5a059; }\r\n.pm-read-badge--read { color: #2ecc71; }\r\n.pm-read-badge--unread { color: #555; }\r\n.pm-empty { color: #333; text-align: center; padding: 40px; font-family: Cinzel; font-size: 11px; letter-spacing: 2px; }\r\n.pm-read-box { background: rgba(255,255,255,0.02); border: 1px solid #1a1a1a; padding: 25px; margin-bottom: 20px; }\r\n.pm-read-header { display: flex; justify-content: space-between; align-items: flex-start; margin-bottom: 20px; padding-bottom: 15px; border-bottom: 1px solid #111; }\r\n.pm-read-subject { font-family: Cinzel; color: #c5a059; font-size: 13px; margin-bottom: 8px; }\r\n.pm-read-from { font-size: 11px; color: #555; }\r\n.pm-read-name { color: #aaa; }\r\n.pm-read-actions { display: flex; gap: 8px; }\r\n.pm-action-btn { background: none; cursor: pointer; font-family: Cinzel; font-size: 9px; padding: 5px 10px; letter-spacing: 1px; transition: 0.2s; }\r\n.pm-action-btn--delete { border: 1px solid #330000; color: #553333; }\r\n.pm-action-btn--delete:hover { border-color: #cc3333; color: #cc3333; }\r\n.pm-action-btn--recall { border: 1px solid #333; color: #888; }\r\n.pm-action-btn--recall:hover { border-color: #c5a059; color: #c5a059; }\r\n.pm-read-body { color: #ccc; line-height: 1.8; font-size: 13px; white-space: pre-wrap; }\r\n.pm-reply-box { background: rgba(197,160,89,0.03); border: 1px solid #1a1a1a; border-top: 2px solid rgba(197,160,89,0.2); padding: 20px; }\r\n.pm-reply-title { font-family: Cinzel; font-size: 10px; color: #555; letter-spacing: 2px; margin-bottom: 15px; }\r\n.pm-compose-box { background: rgba(255,255,255,0.02); border: 1px solid #1a1a1a; border-top: 2px solid rgba(197,160,89,0.2); padding: 25px; }\r\n.pm-field { margin-bottom: 15px; }\r\n.pm-label { display: block; font-family: Cinzel, serif; font-size: 9px; color: #444; letter-spacing: 2px; text-transform: uppercase; margin-bottom: 6px; }\r\n.pm-input { width: 100%; background: #000; border: 1px solid #1a1a1a; color: #ccc; padding: 10px 12px; font-size: 12px; box-sizing: border-box; }\r\n.pm-textarea { width: 100%; background: #000; border: 1px solid #1a1a1a; color: #ccc; padding: 12px; font-size: 12px; resize: vertical; box-sizing: border-box; }\r\n.pm-send-btn { background: rgba(197,160,89,0.05); color: #c5a059; border: 1px solid rgba(197,160,89,0.4); padding: 8px 24px; font-family: Cinzel; font-size: 9px; letter-spacing: 2px; cursor: pointer; transition: 0.3s; text-transform: uppercase; }\r\n.pm-send-btn:hover { background: #c5a059; color: #000; }\r\n.pm-alert { padding: 12px 15px; font-size: 11px; margin-bottom: 15px; background: rgba(0,0,0,0.3); }\r\n.pm-alert--success { border: 1px solid rgba(46,204,113,0.2); color: #2ecc71; }\r\n.pm-alert--error { border: 1px solid rgba(231,76,60,0.2); color: #e74c3c; }', 'Private Messages – Full PM module styles', '2026-08-05 12:44:32', 1),
	(256, 'download_attachment', 'default', '.dav-not-found { padding: 40px 20px; text-align: center; color: #555; } .dav-icon { font-size: 2em; margin-bottom: 16px; display: block; color: #333; } .dav-text { font-size: 0.9em; } .dav-back { display: inline-block; margin-top: 16px; color: var(--glow-blue); font-size: 0.8em; text-decoration: none; }', 'Download Attachment – not found page', '2026-08-05 13:17:56', 1),
	(394, 'dynamic_content', 'default', '\n\n.dynamic-content {\n    color: var(--ald-ink-dim);\n    font-size: 0.98em;\n    line-height: 1.85;\n    letter-spacing: 0.2px;\n    max-width: 78ch;\n}\n\n\n.dynamic-content h1,\n.dynamic-content h2,\n.dynamic-content h3,\n.dynamic-content h4 {\n    font-family: \'Cinzel\', serif;\n    font-weight: 500;\n    color: var(--ald-gold);\n    letter-spacing: 2px;\n    line-height: 1.35;\n    margin: 2.1em 0 0.7em;\n}\n.dynamic-content > :first-child { margin-top: 0; }\n\n.dynamic-content h2 {\n    font-size: 1.5em;\n    color: var(--ald-gold-lt);\n    letter-spacing: 2.6px;\n    padding-bottom: 0.5em;\n    position: relative;\n}\n.dynamic-content h2::after {\n    content: \'\';\n    position: absolute; left: 0; bottom: 0;\n    width: 170px; max-width: 55%; height: 1px;\n    background: linear-gradient(90deg, rgba(197,160,89,0.5), transparent);\n}\n.dynamic-content h3 { font-size: 1.15em; letter-spacing: 2.2px; }\n.dynamic-content h4 { font-size: 1em; color: var(--ald-gold-dk); }\n\n\n.dynamic-content p { margin: 0 0 1.25em; }\n.dynamic-content strong, .dynamic-content b { color: var(--ald-ink); font-weight: 600; }\n.dynamic-content em, .dynamic-content i { color: var(--ald-ink); }\n\n.dynamic-content a {\n    color: var(--ald-gold);\n    text-decoration: none;\n    border-bottom: 1px solid rgba(197,160,89,0.28);\n    transition: color 0.2s, border-color 0.2s;\n}\n.dynamic-content a:hover { color: var(--ald-gold-lt); border-bottom-color: var(--ald-gold); }\n.dynamic-content a.btn-outline-gold,\n.dynamic-content a.btn-gold { border-bottom: 1px solid var(--ald-line); }\n\n\n.dynamic-content ul { list-style: none; padding-left: 0; margin: 0 0 1.4em; }\n.dynamic-content ul li {\n    position: relative;\n    padding-left: 22px;\n    margin-bottom: 0.55em;\n}\n.dynamic-content ul li::before {\n    content: \'\';\n    position: absolute; left: 3px; top: 0.72em;\n    width: 6px; height: 6px;\n    background: var(--orn-diamond-fill) center / 6px 6px no-repeat;\n    opacity: 0.75;\n}\n.dynamic-content ol { padding-left: 20px; margin: 0 0 1.4em; }\n.dynamic-content ol li { margin-bottom: 0.55em; }\n.dynamic-content ol li::marker { color: var(--ald-gold-dk); font-family: \'Cinzel\', serif; }\n\n\n.dynamic-content blockquote {\n    margin: 1.8em 0;\n    padding: 4px 0 4px 22px;\n    border-left: 2px solid rgba(197,160,89,0.35);\n    color: var(--ald-ink);\n    font-family: \'Cormorant Garamond\', Georgia, serif;\n    font-style: italic;\n    font-size: 1.12em;\n    line-height: 1.7;\n}\n\n\n.dynamic-content hr {\n    position: relative;\n    border: none;\n    height: 1px;\n    margin: 2.6em auto;\n    background: linear-gradient(90deg, transparent, var(--ald-line), transparent);\n    overflow: visible;\n}\n.dynamic-content hr::after {\n    content: \'\';\n    position: absolute; top: 50%; left: 50%;\n    width: 11px; height: 11px; margin: -5.5px 0 0 -5.5px;\n    background: var(--orn-diamond) center / 11px 11px no-repeat, #050506;\n    border-radius: 50%;\n}\n\n\n.dynamic-content img { max-width: 100%; height: auto; border: 1px solid var(--ald-line-dead); }\n.dynamic-content table {\n    width: 100%;\n    border-collapse: collapse;\n    margin: 1.6em 0;\n    font-size: 0.92em;\n}\n.dynamic-content th {\n    font-family: \'Cinzel\', serif;\n    font-weight: 500;\n    color: var(--ald-gold);\n    text-align: left;\n    letter-spacing: 1.6px;\n    text-transform: uppercase;\n    font-size: 0.82em;\n    padding: 10px 12px;\n    border-bottom: 1px solid var(--ald-line);\n    background: rgba(197,160,89,0.04);\n}\n.dynamic-content td { padding: 10px 12px; border-bottom: 1px solid var(--ald-line-dead); }\n.dynamic-content tr:hover td { background: rgba(197,160,89,0.025); }\n\n.dynamic-content code {\n    font-family: ui-monospace, Consolas, monospace;\n    font-size: 0.88em;\n    color: var(--ald-gold-lt);\n    background: rgba(0,0,0,0.5);\n    border: 1px solid var(--ald-line-dead);\n    padding: 1px 6px;\n}\n.dynamic-content pre {\n    background: #060607;\n    border: 1px solid var(--ald-line-dead);\n    border-left: 2px solid rgba(197,160,89,0.3);\n    padding: 14px 16px;\n    overflow-x: auto;\n}\n.dynamic-content pre code { border: none; background: none; padding: 0; }\n\n@media screen and (max-width: 900px) {\n    .dynamic-content { font-size: 0.94em; line-height: 1.75; }\n    .dynamic-content h2 { font-size: 1.25em; }\n}\n', 'DAoC CMS typography for Content Manager pages', '2026-08-08 10:49:38', 1);
