INSERT INTO `cms_ai_settings` (`id`, `setting_key`, `setting_value`, `provider`, `module_context`, `description`, `updated_by`, `updated_at`) VALUES
	(1, 'system_base_prompt', 'You are the AI assistant of the DAoC CMS. You NEVER modify data directly. You ONLY analyze, suggest, and generate content. The admin always makes the final decision.', 'all', NULL, 'Global rule: AI must never modify data', NULL, '2026-03-15 17:09:25'),
	(2, 'model_name', 'gemini-2.0-flash', 'gemini', NULL, 'Gemini model', NULL, '2026-03-15 17:09:25'),
	(3, 'model_name', 'local-model', 'lm_studio', NULL, 'LM Studio local model', NULL, '2026-03-15 17:09:25'),
	(4, 'model_name', 'llama3-8b-8192', 'groq', NULL, 'Default Groq model', NULL, '2026-03-15 17:09:25'),
	(5, 'system_prompt', 'You are helping to create items for a Dark Age of Camelot private server. Focus on lore-accurate names, descriptions, and balanced stats. Never suggest values that break game balance.', 'all', 'item_creator', 'System prompt for the item creator', 2, '2026-03-15 17:51:49'),
	(6, 'system_prompt', 'You are helping to create and balance mobs for a Dark Age of Camelot private server. Consider level ranges, faction, spawn density, and lore consistency.', 'all', 'mob_editor', 'System prompt for the mob editor', 2, '2026-03-15 17:51:49'),
	(7, 'system_prompt', 'You are a PHP error analyst. Analyze the provided error log entries and suggest possible fixes. Always explain what caused the error before suggesting a solution.', 'all', 'error_log', 'System prompt for error log analysis', 2, '2026-03-15 17:51:49'),
	(8, 'system_prompt', 'You are a CSS assistant for the DAoC CMS theme editor. The theme uses CSS custom properties (variables). Only suggest valid CSS. Never add JavaScript.', 'all', 'theme_editor', 'System prompt for the theme editor', 2, '2026-03-15 17:51:49'),
