CREATE TABLE IF NOT EXISTS `cms_ai_logs` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `task_id` varchar(36) NOT NULL,
  `user_id` int(10) unsigned DEFAULT NULL,
  `provider` varchar(50) NOT NULL,
  `model` varchar(100) DEFAULT NULL,
  `module_context` varchar(100) DEFAULT NULL,
  `task_type` varchar(100) DEFAULT NULL,
  `prompt_text` text DEFAULT NULL,
  `response_text` text DEFAULT NULL,
  `prompt_tokens` smallint(5) unsigned DEFAULT NULL,
  `completion_tokens` smallint(5) unsigned DEFAULT NULL,
  `duration_ms` smallint(5) unsigned DEFAULT NULL,
  `status` enum('ok','error','timeout','filtered') NOT NULL DEFAULT 'ok',
  `error_message` varchar(500) DEFAULT NULL,
  `ip_address` varchar(45) DEFAULT NULL,
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`id`),
  KEY `idx_user` (`user_id`),
  KEY `idx_module` (`module_context`),
  KEY `idx_status` (`status`),
  KEY `idx_created` (`created_at`),
  KEY `idx_provider` (`provider`),
  KEY `idx_status_date` (`status`,`created_at`),
  KEY `idx_created_at` (`created_at`),
  KEY `idx_task_id` (`task_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

