  `started_at` timestamp NULL DEFAULT NULL,
  `finished_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_task_id` (`task_id`),
  KEY `idx_status_priority` (`status`,`priority`),
  KEY `idx_user` (`user_id`),
