DELIMITER //
CREATE EVENT `daily_login_cleanup` ON SCHEDULE EVERY 1 DAY STARTS '2026-02-27 19:15:14' ON COMPLETION NOT PRESERVE ENABLE DO DELETE FROM `login_attempts` WHERE `last_attempt` < NOW() - INTERVAL 1 DAY//
DELIMITER ;

DELIMITER //
CREATE EVENT `evt_expire_ai_suggestions` ON SCHEDULE EVERY 1 DAY STARTS '2026-03-16 03:00:00' ON COMPLETION NOT PRESERVE ENABLE DO UPDATE cms_ai_suggestions
    SET    status = 'expired'
    WHERE  status = 'pending'
      AND  expires_at IS NOT NULL
      AND  expires_at < NOW()//
DELIMITER ;

DELIMITER //
CREATE EVENT `evt_reset_ai_calls_today` ON SCHEDULE EVERY 1 DAY STARTS '2026-03-16 00:00:00' ON COMPLETION NOT PRESERVE ENABLE DO UPDATE settings
    SET    value = '0'
    WHERE  setting_key = 'ai_calls_today'//
DELIMITER ;

