SET @OLDTMP_SQL_MODE=@@SQL_MODE, SQL_MODE='NO_ENGINE_SUBSTITUTION';
DELIMITER //
CREATE TRIGGER trg_ai_logs_after_insert
AFTER INSERT ON cms_ai_logs
FOR EACH ROW
BEGIN

    VALUES ('ai_calls_today', 1)
    ON DUPLICATE KEY UPDATE
        value = IF(

            (SELECT COALESCE(MAX(DATE(created_at)), CURDATE())
             FROM   cms_ai_logs
             WHERE  id < NEW.id
               AND  DATE(created_at) < CURDATE()) IS NOT NULL
            AND (SELECT COUNT(*) FROM cms_ai_logs
                 WHERE DATE(created_at) < CURDATE() LIMIT 1) > 0,
            1,
            CAST(value AS UNSIGNED) + 1
        );
END//
DELIMITER ;
SET SQL_MODE=@OLDTMP_SQL_MODE;

SET @OLDTMP_SQL_MODE=@@SQL_MODE, SQL_MODE='NO_ENGINE_SUBSTITUTION';
DELIMITER //
CREATE TRIGGER trg_ai_suggestions_after_insert
AFTER INSERT ON cms_ai_suggestions
FOR EACH ROW
BEGIN

    IF NEW.expires_at IS NULL THEN
        UPDATE cms_ai_suggestions
        SET    expires_at = DATE_ADD(NOW(), INTERVAL 7 DAY)
        WHERE  id = NEW.id;
    END IF;
END//
DELIMITER ;
SET SQL_MODE=@OLDTMP_SQL_MODE;

SET @OLDTMP_SQL_MODE=@@SQL_MODE, SQL_MODE='NO_ENGINE_SUBSTITUTION';
DELIMITER //
CREATE TRIGGER trg_ai_suggestions_after_update
AFTER UPDATE ON cms_ai_suggestions
FOR EACH ROW
BEGIN

    IF OLD.status = 'pending' AND NEW.status = 'accepted' THEN
            task_id,
            user_id,
            provider,
            module_context,
            task_type,
            payload,
            priority,
            status,
            queued_at
        ) VALUES (
            CONCAT('apply-', NEW.id, '-', UNIX_TIMESTAMP()),
            NEW.reviewed_by,
            'internal',
            NEW.module_context,
            'apply_suggestion',
            JSON_OBJECT(
                'suggestion_id', NEW.id,
                'target_type',   NEW.target_type,
                'target_id',     NEW.target_id,
                'module',        NEW.module_context,
                'suggestion',    NEW.suggestion_data
            ),
            1,
            'queued',
            NOW()
        );
    END IF;

    IF OLD.status = 'pending' AND NEW.status = 'expired' THEN
            task_id,
            user_id,
            provider,
            module_context,
            task_type,
            status,
            error_message,
            created_at
        ) VALUES (
            NEW.task_id,
            NEW.user_id,
            'internal',
            NEW.module_context,
            'suggestion_expired',
            'ok',
            CONCAT('Suggestion #', NEW.id, ' expired automatically'),
            NOW()
        );
    END IF;
END//
DELIMITER ;
SET SQL_MODE=@OLDTMP_SQL_MODE;

SET @OLDTMP_SQL_MODE=@@SQL_MODE, SQL_MODE='NO_ENGINE_SUBSTITUTION';
DELIMITER //
CREATE TRIGGER trg_ai_suggestions_before_update
BEFORE UPDATE ON cms_ai_suggestions
FOR EACH ROW
BEGIN
    IF OLD.status IN ('accepted', 'rejected')
       AND NEW.status = 'pending' THEN
        SIGNAL SQLSTATE '45000'
        SET MESSAGE_TEXT = 'cms_ai_suggestions: cannot revert accepted/rejected suggestion to pending';
    END IF;

    IF OLD.status = 'pending'
       AND NEW.status IN ('accepted', 'rejected')
       AND NEW.reviewed_at IS NULL THEN
        SET NEW.reviewed_at = NOW();
    END IF;
END//
DELIMITER ;
SET SQL_MODE=@OLDTMP_SQL_MODE;

SET @OLDTMP_SQL_MODE=@@SQL_MODE, SQL_MODE='NO_ENGINE_SUBSTITUTION';
DELIMITER //
CREATE TRIGGER trg_ai_tasks_after_update
AFTER UPDATE ON cms_ai_tasks
FOR EACH ROW
BEGIN

    IF OLD.status IN ('queued','processing')
       AND NEW.status IN ('done','failed','cancelled')
       AND NEW.finished_at IS NULL THEN
        UPDATE cms_ai_tasks
        SET    finished_at = NOW()
        WHERE  task_id = NEW.task_id;
    END IF;

    IF NEW.status = 'failed'
       AND NEW.attempts >= NEW.max_attempts
       AND NEW.task_type = 'apply_suggestion' THEN
        UPDATE cms_ai_suggestions s
        JOIN   (SELECT JSON_UNQUOTE(
                           JSON_EXTRACT(NEW.payload, '$.suggestion_id')
                       ) AS sid) AS p
        SET    s.status = 'expired',
               s.review_note = CONCAT(
                   COALESCE(s.review_note, ''),
                   ' [Auto-expired: apply task failed after ',
                   NEW.attempts,
                   ' attempts]'
               )
        WHERE  s.id = p.sid
          AND  s.status = 'accepted';
    END IF;
END//
DELIMITER ;
SET SQL_MODE=@OLDTMP_SQL_MODE;

SET @OLDTMP_SQL_MODE=@@SQL_MODE, SQL_MODE='NO_ENGINE_SUBSTITUTION';
DELIMITER //
CREATE TRIGGER trg_bot_cmd_perms_before_insert
BEFORE INSERT ON cms_bot_command_permissions
FOR EACH ROW
BEGIN
    IF NEW.scope = 'authlevel' AND (NEW.scope_value < 1 OR NEW.scope_value > 5) THEN
        SIGNAL SQLSTATE '45000'
        SET MESSAGE_TEXT = 'cms_bot_command_permissions: authlevel must be between 1 and 5';
    END IF;
END//
DELIMITER ;
SET SQL_MODE=@OLDTMP_SQL_MODE;

SET @OLDTMP_SQL_MODE=@@SQL_MODE, SQL_MODE='NO_ENGINE_SUBSTITUTION';
DELIMITER //
CREATE TRIGGER trg_bot_commands_before_insert
BEFORE INSERT ON cms_bot_commands
FOR EACH ROW
BEGIN

    SET NEW.command = LOWER(REGEXP_REPLACE(NEW.command, '[^a-z0-9_]', ''));

    IF NEW.command = '' THEN
        SIGNAL SQLSTATE '45000'
        SET MESSAGE_TEXT = 'cms_bot_commands: command cannot be empty after normalization';
    END IF;
END//
DELIMITER ;
SET SQL_MODE=@OLDTMP_SQL_MODE;

SET @OLDTMP_SQL_MODE=@@SQL_MODE, SQL_MODE='NO_ENGINE_SUBSTITUTION';
DELIMITER //
CREATE TRIGGER trg_bot_commands_before_update
BEFORE UPDATE ON cms_bot_commands
FOR EACH ROW
BEGIN
    IF NEW.command != OLD.command THEN
        SET NEW.command = LOWER(REGEXP_REPLACE(NEW.command, '[^a-z0-9_]', ''));
        IF NEW.command = '' THEN
            SIGNAL SQLSTATE '45000'
            SET MESSAGE_TEXT = 'cms_bot_commands: command cannot be empty after normalization';
        END IF;
    END IF;
    SET NEW.updated_at = NOW();
END//
DELIMITER ;
SET SQL_MODE=@OLDTMP_SQL_MODE;
CREATE TABLE IF NOT EXISTS `bot_settings` (
